import{_ as n,C as o,o as e,c as r,j as a,a as i,b as d,w as s,E as h,a2 as c,a3 as g}from"./chunks/framework.pb1iZPmZ.js";const w=JSON.parse('{"title":"Step 5: Technology Choice Comparisons","description":"","frontmatter":{},"headers":[],"relativePath":"04-tech-comparisons.md","filePath":"04-tech-comparisons.md"}'),u={name:"04-tech-comparisons.md"};function f(y,t,p,m,x,b){const l=o("Mermaid");return e(),r("div",null,[t[1]||(t[1]=a("h1",{id:"step-5-technology-choice-comparisons",tabindex:"-1"},[i("Step 5: Technology Choice Comparisons "),a("a",{class:"header-anchor",href:"#step-5-technology-choice-comparisons","aria-label":'Permalink to "Step 5: Technology Choice Comparisons"'},"​")],-1)),(e(),d(c,null,{default:s(()=>[h(l,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20Choices%5B%22Technology%20Choices%20in%20This%20Project%22%5D%0A%20%20%20%20%20%20%20%20DB%5B%22MongoDB%20%2B%20Mongoose%209%20(Database)%22%5D%0A%20%20%20%20%20%20%20%20Sess%5B%22connect-mongo%20(Session%20Store)%22%5D%0A%20%20%20%20%20%20%20%20FW%5B%22Express%205.1.0%20(Web%20Framework)%22%5D%0A%20%20%20%20%20%20%20%20Front%5B%22Vanilla%20JS%20%2B%20CSS%20Glassmorphism%20%2B%20EJS%20(UI%20Tier)%22%5D%0A%20%20%20%20%20%20%20%20View%5B%22EJS%203.1.10%20(SSR%20Template%20Engine)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20DB%20---%20Sess%20---%20FW%20---%20Front%20---%20View%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=g('<hr><h2 id="_1-database-layer-mongodb-mongoose-vs-alternatives" tabindex="-1">1. Database Layer: MongoDB (Mongoose) vs Alternatives <a class="header-anchor" href="#_1-database-layer-mongodb-mongoose-vs-alternatives" aria-label="Permalink to &quot;1. Database Layer: MongoDB (Mongoose) vs Alternatives&quot;">​</a></h2><h3 id="_1-what-i-used" tabindex="-1">1. What I Used <a class="header-anchor" href="#_1-what-i-used" aria-label="Permalink to &quot;1. What I Used&quot;">​</a></h3><p>MongoDB connected via Mongoose ODM v9.0.0 ([<code>app.js:5,12-24</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L5)).</p><h3 id="_2-what-it-does-in-this-project" tabindex="-1">2. What It Does in This Project <a class="header-anchor" href="#_2-what-it-does-in-this-project" aria-label="Permalink to &quot;2. What It Does in This Project&quot;">​</a></h3><p>Stores employee identity records in the <code>employees</code> collection and serves as the durable backing store for user session documents in the <code>sessions</code> collection.</p><h3 id="_3-exhaustive-comparison-table" tabindex="-1">3. Exhaustive Comparison Table <a class="header-anchor" href="#_3-exhaustive-comparison-table" aria-label="Permalink to &quot;3. Exhaustive Comparison Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Database Engine</th><th style="text-align:left;">Data Model</th><th style="text-align:left;">ACID Support</th><th style="text-align:left;">Query Language</th><th style="text-align:left;">Schema Flexibility</th><th style="text-align:left;">Connection Overhead</th><th style="text-align:left;">Fit With Node.js / This Portal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>MongoDB (Chosen)</strong></td><td style="text-align:left;"><strong>Document (BSON)</strong></td><td style="text-align:left;"><strong>Document ACID (Multi-doc via replica sets)</strong></td><td style="text-align:left;"><strong>Mongoose Query / Aggregation</strong></td><td style="text-align:left;"><strong>Dynamic / Flexible</strong></td><td style="text-align:left;"><strong>Medium (Built-in connection pool)</strong></td><td style="text-align:left;"><strong>High (Native JSON/BSON, directly supports connect-mongo)</strong></td></tr><tr><td style="text-align:left;"><strong>PostgreSQL</strong></td><td style="text-align:left;">Relational / Object</td><td style="text-align:left;">Full ACID (Multi-row transactions)</td><td style="text-align:left;">SQL</td><td style="text-align:left;">Strict / Static</td><td style="text-align:left;">High (Requires connection pooler like PgBouncer)</td><td style="text-align:left;">High (Standard SQL, but requires schema migrations)</td></tr><tr><td style="text-align:left;"><strong>MySQL</strong></td><td style="text-align:left;">Relational</td><td style="text-align:left;">Full ACID (InnoDB)</td><td style="text-align:left;">SQL</td><td style="text-align:left;">Strict / Static</td><td style="text-align:left;">High</td><td style="text-align:left;">Medium (Standard, but rigid for fast schema iteration)</td></tr><tr><td style="text-align:left;"><strong>CockroachDB</strong></td><td style="text-align:left;">Distributed Relational</td><td style="text-align:left;">Multi-region distributed ACID</td><td style="text-align:left;">SQL</td><td style="text-align:left;">Strict</td><td style="text-align:left;">High</td><td style="text-align:left;">Overkill (Massive distributed overhead for a single portal)</td></tr><tr><td style="text-align:left;"><strong>Redis</strong></td><td style="text-align:left;">In-Memory Key-Value</td><td style="text-align:left;">Single-command atomicity</td><td style="text-align:left;">Redis commands</td><td style="text-align:left;">Key-value structures</td><td style="text-align:left;">Low (Extremely lightweight)</td><td style="text-align:left;">High for sessions, Low for durable employee records</td></tr><tr><td style="text-align:left;"><strong>Amazon DynamoDB</strong></td><td style="text-align:left;">Managed NoSQL / Key-Value</td><td style="text-align:left;">ACID via TransactItems</td><td style="text-align:left;">DynamoDB API / PartiQL</td><td style="text-align:left;">Flexible</td><td style="text-align:left;">Low (HTTP-based)</td><td style="text-align:left;">Vendor-locked to AWS, complex local simulation</td></tr><tr><td style="text-align:left;"><strong>Firebase Firestore</strong></td><td style="text-align:left;">Document NoSQL</td><td style="text-align:left;">Document ACID</td><td style="text-align:left;">Firestore SDK</td><td style="text-align:left;">Flexible</td><td style="text-align:left;">Low (Managed)</td><td style="text-align:left;">Heavy client SDK lock-in, proprietary cloud dependencies</td></tr><tr><td style="text-align:left;"><strong>SQLite</strong></td><td style="text-align:left;">Embedded Relational</td><td style="text-align:left;">Full ACID (Single file)</td><td style="text-align:left;">SQL</td><td style="text-align:left;">Strict</td><td style="text-align:left;">Zero</td><td style="text-align:left;">File lock bottlenecks on concurrent writes</td></tr><tr><td style="text-align:left;"><strong>Supabase</strong></td><td style="text-align:left;">Managed PostgreSQL</td><td style="text-align:left;">Full ACID</td><td style="text-align:left;">PostgREST / SQL</td><td style="text-align:left;">Strict</td><td style="text-align:left;">High</td><td style="text-align:left;">Cloud wrapper; unnecessary overhead for local custom Express server</td></tr></tbody></table><h3 id="_5-why-i-used-this" tabindex="-1">5. Why I Used This <a class="header-anchor" href="#_5-why-i-used-this" aria-label="Permalink to &quot;5. Why I Used This&quot;">​</a></h3><p>MongoDB was chosen because its native JSON document paradigm maps directly to JavaScript objects without impedance mismatch. Crucially, using MongoDB allowed both employee identities and web session storage (<code>connect-mongo</code>) to share a single, unified database infrastructure without deploying a separate Redis cluster [CONFIRM WITH DEVELOPER].</p><h3 id="_6-why-i-did-not-use-each-alternative" tabindex="-1">6. Why I Did NOT Use Each Alternative <a class="header-anchor" href="#_6-why-i-did-not-use-each-alternative" aria-label="Permalink to &quot;6. Why I Did NOT Use Each Alternative&quot;">​</a></h3><ul><li><strong>PostgreSQL</strong>: Required setting up schema migration runners (<code>Knex</code>/<code>TypeORM</code>) and rigid column types before rapid prototype iteration could occur.</li><li><strong>MySQL</strong>: Offered no document flexibility and requires external table definitions for session stores.</li><li><strong>CockroachDB</strong>: Carries immense architectural complexity and hardware overhead designed for multi-region geo-replication that this single-region portal does not require.</li><li><strong>Redis</strong>: Stores data primarily in RAM; using it as the sole database risks data loss on node reboot unless expensive disk append policies (AOF) are configured.</li><li><strong>DynamoDB</strong>: Would tie the project to Amazon Web Services and make local offline execution cumbersome.</li><li><strong>Firebase Firestore</strong>: Imposes proprietary Google SDKs and pricing tiers that prevent self-hosted on-premise hospital deployment.</li><li><strong>SQLite</strong>: Lacks robust support for high-concurrency write operations due to table-level file locking.</li><li><strong>Supabase</strong>: Wraps PostgreSQL behind client REST libraries, conflicting with our goal of writing clean, native Express backend controllers.</li></ul><h3 id="_7-benefits-provided" tabindex="-1">7. Benefits Provided <a class="header-anchor" href="#_7-benefits-provided" aria-label="Permalink to &quot;7. Benefits Provided&quot;">​</a></h3><ul><li>Zero schema migration friction during initial employee field additions.</li><li>Unified storage: a single MongoDB daemon hosts both persistent employee data and transient user sessions.</li><li>Out-of-the-box MongoDB TTL indexes manage session expiry automatically.</li></ul><h3 id="_8-drawbacks-trade-offs-accepted" tabindex="-1">8. Drawbacks &amp; Trade-offs Accepted <a class="header-anchor" href="#_8-drawbacks-trade-offs-accepted" aria-label="Permalink to &quot;8. Drawbacks &amp; Trade-offs Accepted&quot;">​</a></h3><ul><li>Joins and referential integrity must be manually enforced at the application layer rather than guaranteed by database constraints.</li><li>Default Mongoose installation does not automatically create unique indexes unless explicitly configured.</li></ul><h3 id="_9-when-i-would-switch" tabindex="-1">9. When I Would Switch <a class="header-anchor" href="#_9-when-i-would-switch" aria-label="Permalink to &quot;9. When I Would Switch&quot;">​</a></h3><p>I would switch to PostgreSQL if the hospital system expands to require complex relational joins (e.g. linking patients to doctors, medical billing records, prescriptions, and insurance claims) where relational foreign keys and strict ACID transactions across multiple tables are legally mandated.</p><h3 id="_10-30-second-spoken-answer" tabindex="-1">10. 30-Second Spoken Answer <a class="header-anchor" href="#_10-30-second-spoken-answer" aria-label="Permalink to &quot;10. 30-Second Spoken Answer&quot;">​</a></h3><blockquote><p>&quot;I chose MongoDB with Mongoose because its document model aligns naturally with JavaScript, and it allowed me to use a single database instance for both employee records and persistent session storage through <code>connect-mongo</code>. While PostgreSQL is outstanding for relational healthcare records, MongoDB eliminated schema migration friction and allowed me to leverage native TTL indexes for automatic session expiration.&quot;</p></blockquote><hr><h2 id="_2-authentication-strategy-stateful-server-sessions-vs-jwt-vs-alternatives" tabindex="-1">2. Authentication Strategy: Stateful Server Sessions vs JWT vs Alternatives <a class="header-anchor" href="#_2-authentication-strategy-stateful-server-sessions-vs-jwt-vs-alternatives" aria-label="Permalink to &quot;2. Authentication Strategy: Stateful Server Sessions vs JWT vs Alternatives&quot;">​</a></h2><h3 id="_1-what-i-used-1" tabindex="-1">1. What I Used <a class="header-anchor" href="#_1-what-i-used-1" aria-label="Permalink to &quot;1. What I Used&quot;">​</a></h3><p>Stateful server-side sessions using <code>express-session</code> backed by <code>connect-mongo</code> in MongoDB ([<code>app.js:4,6,30-36</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L4)).</p><h3 id="_2-what-it-does-in-this-project-1" tabindex="-1">2. What It Does in This Project <a class="header-anchor" href="#_2-what-it-does-in-this-project-1" aria-label="Permalink to &quot;2. What It Does in This Project&quot;">​</a></h3><p>Generates a cryptographically signed cookie (<code>connect.sid</code>), stores session state in MongoDB, and maintains user authentication state between HTTP requests.</p><h3 id="_3-exhaustive-comparison-table-1" tabindex="-1">3. Exhaustive Comparison Table <a class="header-anchor" href="#_3-exhaustive-comparison-table-1" aria-label="Permalink to &quot;3. Exhaustive Comparison Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Auth Mechanism</th><th style="text-align:left;">State Location</th><th style="text-align:left;">Invalidation Speed</th><th style="text-align:left;">Network Payload Size</th><th style="text-align:left;">Multi-Server Scalability</th><th style="text-align:left;">Revocation Feasibility</th><th style="text-align:left;">XSS / CSRF Vulnerability Profile</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>MongoDB Sessions (Chosen)</strong></td><td style="text-align:left;"><strong>Server DB (MongoDB)</strong></td><td style="text-align:left;"><strong>Instantaneous (Delete DB row)</strong></td><td style="text-align:left;"><strong>Minimal (~50 bytes cookie)</strong></td><td style="text-align:left;"><strong>High (Shared database pool)</strong></td><td style="text-align:left;"><strong>Immediate (On logout or admin action)</strong></td><td style="text-align:left;"><strong>Safe from XSS if httpOnly; Needs CSRF defense</strong></td></tr><tr><td style="text-align:left;"><strong>Stateless JWT</strong></td><td style="text-align:left;">Client (Storage/Cookie)</td><td style="text-align:left;">Impossible without blacklist</td><td style="text-align:left;">Large (~500–1000 bytes header)</td><td style="text-align:left;">Infinite (No DB query needed)</td><td style="text-align:left;">Impossible until token expires</td><td style="text-align:left;">Dangerous in localStorage (XSS); Cookie requires CSRF token</td></tr><tr><td style="text-align:left;"><strong>Redis Sessions</strong></td><td style="text-align:left;">Server RAM (Redis)</td><td style="text-align:left;">Instantaneous (&lt;1ms)</td><td style="text-align:left;">Minimal (~50 bytes)</td><td style="text-align:left;">High (Shared Redis instance)</td><td style="text-align:left;">Immediate</td><td style="text-align:left;">Same as Mongo session</td></tr><tr><td style="text-align:left;"><strong>In-Memory Express Sessions</strong></td><td style="text-align:left;">Server RAM (Node process)</td><td style="text-align:left;">Instantaneous</td><td style="text-align:left;">Minimal</td><td style="text-align:left;">Zero (Sessions lost on multi-core / restart)</td><td style="text-align:left;">Immediate</td><td style="text-align:left;">Unsuitable for production</td></tr><tr><td style="text-align:left;"><strong>OAuth2 / OpenID Connect</strong></td><td style="text-align:left;">Third-Party Provider</td><td style="text-align:left;">Dependent on IdP</td><td style="text-align:left;">High</td><td style="text-align:left;">High</td><td style="text-align:left;">Managed by identity provider</td><td style="text-align:left;">Complex integration</td></tr></tbody></table><h3 id="_5-why-i-used-this-1" tabindex="-1">5. Why I Used This <a class="header-anchor" href="#_5-why-i-used-this-1" aria-label="Permalink to &quot;5. Why I Used This&quot;">​</a></h3><p>In a healthcare environment where clinicians share workstations, immediate access revocation is critical. With stateful sessions, calling <code>req.session.destroy()</code> deletes the session document from MongoDB immediately. If an attacker recovers an old cookie, it is instantly invalid [CONFIRM WITH DEVELOPER].</p><h3 id="_6-why-i-did-not-use-each-alternative-1" tabindex="-1">6. Why I Did NOT Use Each Alternative <a class="header-anchor" href="#_6-why-i-did-not-use-each-alternative-1" aria-label="Permalink to &quot;6. Why I Did NOT Use Each Alternative&quot;">​</a></h3><ul><li><strong>Stateless JWT</strong>: Cannot be revoked on demand without maintaining a server-side token blacklist, which defeats the purpose of being stateless.</li><li><strong>Redis Sessions</strong>: While faster than MongoDB, adding Redis would have introduced an extra infrastructure component and deployment requirement for a single server application.</li><li><strong>In-Memory Sessions (<code>MemoryStore</code>)</strong>: Express&#39;s default memory store leaks memory and drops all logged-in users whenever the Node server restarts or scales to multiple processes.</li><li><strong>OAuth2 (Google/Facebook)</strong>: Requires external internet connectivity, which violates internal air-gapped hospital network compliance requirements.</li></ul><h3 id="_7-benefits-provided-1" tabindex="-1">7. Benefits Provided <a class="header-anchor" href="#_7-benefits-provided-1" aria-label="Permalink to &quot;7. Benefits Provided&quot;">​</a></h3><ul><li>True instant revocation on logout.</li><li>Persistent sessions that survive server crashes and redeployments.</li><li>Automatic document cleanup via MongoDB&#39;s background TTL thread.</li></ul><h3 id="_8-drawbacks-trade-offs-accepted-1" tabindex="-1">8. Drawbacks &amp; Trade-offs Accepted <a class="header-anchor" href="#_8-drawbacks-trade-offs-accepted-1" aria-label="Permalink to &quot;8. Drawbacks &amp; Trade-offs Accepted&quot;">​</a></h3><ul><li>Incurs a database query to MongoDB on incoming authenticated requests.</li><li>MongoDB write latency for session creation is higher than in-memory Redis (~5ms vs &lt;1ms).</li></ul><h3 id="_9-when-i-would-switch-1" tabindex="-1">9. When I Would Switch <a class="header-anchor" href="#_9-when-i-would-switch-1" aria-label="Permalink to &quot;9. When I Would Switch&quot;">​</a></h3><p>I would introduce Redis as a caching layer in front of <code>connect-mongo</code> if concurrent daily active sessions exceed 50,000, offloading session read traffic from MongoDB disk to RAM.</p><h3 id="_10-30-second-spoken-answer-1" tabindex="-1">10. 30-Second Spoken Answer <a class="header-anchor" href="#_10-30-second-spoken-answer-1" aria-label="Permalink to &quot;10. 30-Second Spoken Answer&quot;">​</a></h3><blockquote><p>&quot;I chose stateful sessions backed by <code>connect-mongo</code> over stateless JWTs because in a medical portal, instant session revocation is a strict security requirement. With JWTs, you cannot easily revoke a token if a clinician forgets to log off or an employee is terminated. Stateful MongoDB sessions allow immediate revocation on <code>/logout</code> while surviving server restarts.&quot;</p></blockquote><hr><h2 id="_3-web-framework-express-5-vs-alternatives" tabindex="-1">3. Web Framework: Express 5 vs Alternatives <a class="header-anchor" href="#_3-web-framework-express-5-vs-alternatives" aria-label="Permalink to &quot;3. Web Framework: Express 5 vs Alternatives&quot;">​</a></h2><h3 id="_1-what-i-used-2" tabindex="-1">1. What I Used <a class="header-anchor" href="#_1-what-i-used-2" aria-label="Permalink to &quot;1. What I Used&quot;">​</a></h3><p>Express.js v5.1.0 ([<code>package.json:16</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/package.json#L16), [<code>app.js:1</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L1)).</p><h3 id="_2-what-it-does-in-this-project-2" tabindex="-1">2. What It Does in This Project <a class="header-anchor" href="#_2-what-it-does-in-this-project-2" aria-label="Permalink to &quot;2. What It Does in This Project&quot;">​</a></h3><p>Handles the entire backend HTTP server lifecycle, middleware pipeline, static asset delivery, and route dispatching.</p><h3 id="_3-exhaustive-comparison-table-2" tabindex="-1">3. Exhaustive Comparison Table <a class="header-anchor" href="#_3-exhaustive-comparison-table-2" aria-label="Permalink to &quot;3. Exhaustive Comparison Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Framework</th><th style="text-align:left;">Runtime / Language</th><th style="text-align:left;">Paradigm</th><th style="text-align:left;">Async / Promise Handling</th><th style="text-align:left;">Learning Curve</th><th style="text-align:left;">Community Ecosystem</th><th style="text-align:left;">Production Overhead</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Express 5 (Chosen)</strong></td><td style="text-align:left;"><strong>Node.js (JS)</strong></td><td style="text-align:left;"><strong>Minimalist / Unopinionated</strong></td><td style="text-align:left;"><strong>Native Promise / Async-Await support</strong></td><td style="text-align:left;"><strong>Very Low</strong></td><td style="text-align:left;"><strong>Massive (De facto standard)</strong></td><td style="text-align:left;"><strong>Extremely Low</strong></td></tr><tr><td style="text-align:left;"><strong>NestJS</strong></td><td style="text-align:left;">Node.js (TypeScript)</td><td style="text-align:left;">Opinionated / Angular-like</td><td style="text-align:left;">Native</td><td style="text-align:left;">High</td><td style="text-align:left;">Large enterprise</td><td style="text-align:left;">Heavy (Decorators, DI modules, reflection)</td></tr><tr><td style="text-align:left;"><strong>Fastify</strong></td><td style="text-align:left;">Node.js (JS/TS)</td><td style="text-align:left;">Schema-driven / High performance</td><td style="text-align:left;">Native</td><td style="text-align:left;">Low</td><td style="text-align:left;">Growing rapidly</td><td style="text-align:left;">Low (JSON schema serialization overhead)</td></tr><tr><td style="text-align:left;"><strong>Koa</strong></td><td style="text-align:left;">Node.js (JS)</td><td style="text-align:left;">Bare-bones Middleware</td><td style="text-align:left;">Native</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Moderate</td><td style="text-align:left;">Requires assembling every utility manually</td></tr><tr><td style="text-align:left;"><strong>Django</strong></td><td style="text-align:left;">Python</td><td style="text-align:left;">Full-battery Web Framework</td><td style="text-align:left;">Async in Django 4+</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Massive</td><td style="text-align:left;">Heavy (Enforces ORM, admin, migrations)</td></tr><tr><td style="text-align:left;"><strong>Spring Boot</strong></td><td style="text-align:left;">Java</td><td style="text-align:left;">Enterprise Modular</td><td style="text-align:left;">Reactive / Threads</td><td style="text-align:left;">Very High</td><td style="text-align:left;">Massive</td><td style="text-align:left;">Extremely Heavy (JVM memory footprint)</td></tr><tr><td style="text-align:left;"><strong>Go (Gin / Fiber)</strong></td><td style="text-align:left;">Go</td><td style="text-align:left;">Compiled Binary</td><td style="text-align:left;">Goroutines</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Moderate</td><td style="text-align:left;">Requires compiled deployments and static binaries</td></tr></tbody></table><h3 id="_5-why-i-used-this-2" tabindex="-1">5. Why I Used This <a class="header-anchor" href="#_5-why-i-used-this-2" aria-label="Permalink to &quot;5. Why I Used This&quot;">​</a></h3><p>Express 5 provides native asynchronous error handling without the nested try-catch wrappers required in Express 4, while preserving the battle-tested simplicity and universal compatibility of the Express middleware ecosystem [CONFIRM WITH DEVELOPER].</p><h3 id="_6-why-i-did-not-use-each-alternative-2" tabindex="-1">6. Why I Did NOT Use Each Alternative <a class="header-anchor" href="#_6-why-i-did-not-use-each-alternative-2" aria-label="Permalink to &quot;6. Why I Did NOT Use Each Alternative&quot;">​</a></h3><ul><li><strong>NestJS</strong>: Adds excessive boilerplate, dependency injection containers, and TypeScript compilation overhead that slows down small-to-medium portal development.</li><li><strong>Fastify</strong>: While marginally faster in micro-benchmarks, Express 5 provides broader ecosystem support for session stores like <code>connect-mongo</code>.</li><li><strong>Koa</strong>: Lacks built-in routing and request body parsing, requiring multiple third-party libraries just to establish basic CRUD.</li><li><strong>Django</strong>: Enforces Python and an ORM that is heavily biased toward SQL databases rather than MongoDB.</li><li><strong>Spring Boot</strong>: Requires a heavy JVM runtime consuming 500MB+ of baseline RAM, making it inappropriate for lightweight containerized services.</li><li><strong>Go Gin</strong>: Would eliminate the unified JavaScript language stack between backend and frontend scripts.</li></ul><h3 id="_7-benefits-provided-2" tabindex="-1">7. Benefits Provided <a class="header-anchor" href="#_7-benefits-provided-2" aria-label="Permalink to &quot;7. Benefits Provided&quot;">​</a></h3><ul><li>Express 5 natively catches rejected Promises in async route handlers and forwards them to error middleware.</li><li>Near-zero memory overhead and sub-second boot time.</li></ul><h3 id="_8-drawbacks-trade-offs-accepted-2" tabindex="-1">8. Drawbacks &amp; Trade-offs Accepted <a class="header-anchor" href="#_8-drawbacks-trade-offs-accepted-2" aria-label="Permalink to &quot;8. Drawbacks &amp; Trade-offs Accepted&quot;">​</a></h3><ul><li>No built-in architecture enforcement; clean routing and folder structure must be maintained by the developer.</li></ul><h3 id="_9-when-i-would-switch-2" tabindex="-1">9. When I Would Switch <a class="header-anchor" href="#_9-when-i-would-switch-2" aria-label="Permalink to &quot;9. When I Would Switch&quot;">​</a></h3><p>I would switch to NestJS or Fastify if our team grew past 15 backend engineers working in a shared monorepo where strict TypeScript interfaces, dependency injection, and auto-generated Swagger OpenAPI specifications are mandatory.</p><h3 id="_10-30-second-spoken-answer-2" tabindex="-1">10. 30-Second Spoken Answer <a class="header-anchor" href="#_10-30-second-spoken-answer-2" aria-label="Permalink to &quot;10. 30-Second Spoken Answer&quot;">​</a></h3><blockquote><p>&quot;I used Express 5 because it is lightweight, unopinionated, and now features native async-await error handling. It allows me to build clean, middleware-driven request pipelines without the massive boilerplate of NestJS or the language context-switching of Django.&quot;</p></blockquote><hr><h2 id="_4-frontend-strategy-vanilla-js-css-glassmorphism-ejs-vs-react-spa" tabindex="-1">4. Frontend Strategy: Vanilla JS + CSS Glassmorphism + EJS vs React SPA <a class="header-anchor" href="#_4-frontend-strategy-vanilla-js-css-glassmorphism-ejs-vs-react-spa" aria-label="Permalink to &quot;4. Frontend Strategy: Vanilla JS + CSS Glassmorphism + EJS vs React SPA&quot;">​</a></h2><h3 id="_1-what-i-used-3" tabindex="-1">1. What I Used <a class="header-anchor" href="#_1-what-i-used-3" aria-label="Permalink to &quot;1. What I Used&quot;">​</a></h3><p>Static HTML5 with Vanilla JavaScript 3D Parallax and Server-Side Rendered EJS templates ([<code>login.html</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/login.html), [<code>dashboard.ejs</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/dashboard.ejs)).</p><h3 id="_2-what-it-does-in-this-project-3" tabindex="-1">2. What It Does in This Project <a class="header-anchor" href="#_2-what-it-does-in-this-project-3" aria-label="Permalink to &quot;2. What It Does in This Project&quot;">​</a></h3><p>Renders the client authentication interface with hardware-accelerated 3D mouse parallax tilt and dynamically outputs the personalized dashboard directly from the server.</p><h3 id="_3-exhaustive-comparison-table-3" tabindex="-1">3. Exhaustive Comparison Table <a class="header-anchor" href="#_3-exhaustive-comparison-table-3" aria-label="Permalink to &quot;3. Exhaustive Comparison Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Approach</th><th style="text-align:left;">Bundle Size</th><th style="text-align:left;">Initial Page Load (FCP)</th><th style="text-align:left;">Hydration Overhead</th><th style="text-align:left;">SEO / Crawler Indexing</th><th style="text-align:left;">Maintenance Complexity</th><th style="text-align:left;">Hardware Utilization</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Vanilla JS + EJS (Chosen)</strong></td><td style="text-align:left;"><strong>0 KB JS Bundle</strong></td><td style="text-align:left;"><strong>Instantaneous (&lt;100ms)</strong></td><td style="text-align:left;"><strong>Zero (Native DOM)</strong></td><td style="text-align:left;"><strong>Excellent (Pure HTML)</strong></td><td style="text-align:left;"><strong>Extremely Low</strong></td><td style="text-align:left;"><strong>GPU-accelerated CSS transforms</strong></td></tr><tr><td style="text-align:left;"><strong>React SPA (Vite/CRA)</strong></td><td style="text-align:left;">~150–300 KB JS</td><td style="text-align:left;">Slower (Wait for bundle)</td><td style="text-align:left;">Heavy (Virtual DOM reconciliation)</td><td style="text-align:left;">Poor without SSR</td><td style="text-align:left;">High (State management, routers)</td><td style="text-align:left;">Virtual DOM diffing</td></tr><tr><td style="text-align:left;"><strong>Next.js (React SSR)</strong></td><td style="text-align:left;">~250–500 KB JS</td><td style="text-align:left;">Fast</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Excellent</td><td style="text-align:left;">High (Complex server/client boundary)</td><td style="text-align:left;">Node server + React hydration</td></tr><tr><td style="text-align:left;"><strong>Vue.js / Nuxt</strong></td><td style="text-align:left;">~100–250 KB JS</td><td style="text-align:left;">Fast</td><td style="text-align:left;">Medium</td><td style="text-align:left;">Excellent</td><td style="text-align:left;">Moderate</td><td style="text-align:left;">Vue reactivity engine</td></tr><tr><td style="text-align:left;"><strong>Three.js / WebGL</strong></td><td style="text-align:left;">~600 KB JS</td><td style="text-align:left;">Heavy initial download</td><td style="text-align:left;">N/A</td><td style="text-align:left;">Irrelevant</td><td style="text-align:left;">High</td><td style="text-align:left;">Heavy GPU canvas rendering</td></tr></tbody></table><h3 id="_5-why-i-used-this-3" tabindex="-1">5. Why I Used This <a class="header-anchor" href="#_5-why-i-used-this-3" aria-label="Permalink to &quot;5. Why I Used This&quot;">​</a></h3><p>For a dedicated authentication gateway, importing a 300KB React bundle and configuring client-side state libraries like Redux is architectural over-engineering. Writing the 3D parallax tilt in 20 lines of vanilla JavaScript delivered modern visuals with zero bundle weight and instant page rendering [CONFIRM WITH DEVELOPER].</p><h3 id="_6-why-i-did-not-use-each-alternative-3" tabindex="-1">6. Why I Did NOT Use Each Alternative <a class="header-anchor" href="#_6-why-i-did-not-use-each-alternative-3" aria-label="Permalink to &quot;6. Why I Did NOT Use Each Alternative&quot;">​</a></h3><ul><li><strong>React SPA</strong>: Introduces bundle download delays, blank screen flash during hydration, and requires separate client-side auth state synchronisation.</li><li><strong>Next.js</strong>: Adds substantial deployment complexity and serverless abstraction layers unnecessary for a straightforward authentication portal.</li><li><strong>Vue.js</strong>: Still requires client-side bundlers and build steps to compile single-file components.</li><li><strong>Three.js</strong>: Excessively heavy for a card tilt effect that can be achieved using native CSS3 <code>rotateX</code> and <code>rotateY</code> transforms.</li></ul><h3 id="_7-benefits-provided-3" tabindex="-1">7. Benefits Provided <a class="header-anchor" href="#_7-benefits-provided-3" aria-label="Permalink to &quot;7. Benefits Provided&quot;">​</a></h3><ul><li>Instantaneous First Contentful Paint (FCP) on hospital low-spec terminals.</li><li>Zero build tools or transpilers (Babel/Webpack) required for the frontend.</li><li>Hardware-accelerated 60 FPS tilt animations using the browser&#39;s GPU compositing engine.</li></ul><h3 id="_8-drawbacks-trade-offs-accepted-3" tabindex="-1">8. Drawbacks &amp; Trade-offs Accepted <a class="header-anchor" href="#_8-drawbacks-trade-offs-accepted-3" aria-label="Permalink to &quot;8. Drawbacks &amp; Trade-offs Accepted&quot;">​</a></h3><ul><li>Lacks declarative two-way data binding for highly complex, multi-step interactive forms.</li></ul><h3 id="_9-when-i-would-switch-3" tabindex="-1">9. When I Would Switch <a class="header-anchor" href="#_9-when-i-would-switch-3" aria-label="Permalink to &quot;9. When I Would Switch&quot;">​</a></h3><p>I would adopt React or Next.js if the post-login dashboard evolved into an extensive Clinical Electronic Health Record (EHR) application with interactive patient vitals charts, real-time messaging, and multi-tab workflows.</p><h3 id="_10-30-second-spoken-answer-3" tabindex="-1">10. 30-Second Spoken Answer <a class="header-anchor" href="#_10-30-second-spoken-answer-3" aria-label="Permalink to &quot;10. 30-Second Spoken Answer&quot;">​</a></h3><blockquote><p>&quot;Instead of shipping a heavy React bundle for an authentication gateway, I chose Vanilla JavaScript with CSS glassmorphism and server-rendered EJS. It loads instantly on low-spec hospital terminals, has zero client-side dependencies, and achieves 60 FPS 3D parallax tilt using native GPU CSS transforms.&quot;</p></blockquote>',80))])}const S=n(u,[["render",f]]);export{w as __pageData,S as default};
